def envanter_esyasi_kullan(self):
        if not self.envanter:
            return {
                'oyuncu': self.isim,
                'basarili': False,
                'mesaj': 'Kullanılacak eşya yok.'
            }

        esya = self.envanter.pop(0)
        if isinstance(esya, dict):
            kazanilan_xp = esya.get('deger', esya.get('xp', 10))
        else:
            kazanilan_xp = 10

        if not isinstance(kazanilan_xp, (int, float)) or kazanilan_xp < 0:
            kazanilan_xp = 10

        eski_seviye = self.seviye
        self.xp += kazanilan_xp

        while self.xp >= self.seviye * 100:
            self.seviye += 1

        return {
            'oyuncu': self.isim,
            'basarili': True,
            'kullanilan_esya': esya,
            'kazanilan_xp': kazanilan_xp,
            'toplam_xp': self.xp,
            'eski_seviye': eski_seviye,
            'yeni_seviye': self.seviye,
            'seviye_atlama_sayisi': self.seviye - eski_seviye,
            'envanter_sayisi': len(self.envanter)
        }
